-- LOCAL ONLY: synthetic schema matching verified column names, not production data.
-- Types for enums are intentionally text; this is not a substitute for live JWT/RLS verification.
\set ON_ERROR_STOP on
do $$ begin
 if current_database()<>'analytics_task03' or inet_server_port() is distinct from 55439 then
  raise exception 'LOCAL_ANALYTICS_FIXTURE_REQUIRED';
 end if;
end $$;
create schema auth;
create schema account_private;
create table auth.users(id uuid, created_at timestamptz);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function public.admin_operator() returns boolean language sql stable as $$ select auth.uid()='00000000-0000-0000-0000-000000000001'::uuid $$;
create function account_private.allowed(uuid) returns boolean language sql stable as $$ select $1 is not null $$;
grant usage on schema auth to authenticated, anon, service_role;
grant execute on function auth.uid() to authenticated,anon,service_role;
